quests[47000] = { id = 47000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf des Rats", description = "Es tut mir leid, dass ich Euch nicht über die Situation auf dem Laufenden gehalten habe. Wir brauchten mehr verwendbare Informationen, bevor wir Euch mit dem Thema behelligen wollten.\n\nDer Rat der Sechs hat Bedrohungen durch die Legion abseits der Verheerten Küste untersucht. Ich glaube, diese Schriftrolle ist die letzte Information, die uns fehlt.\n\nTrefft mich in der Violetten Zitadelle in Dalaran. Wir brauchen die Hilfe der anderen Ratsmitglieder.", sourceObjective = "Begebt Euch zum Rat der Sechs in der Violetten Zitadelle.", completion = "<Khadgar nickt Euch zu.>\n\nEs freut mich, dass Ihr gekommen seid, Erzmagier.", sourceObjectiveStatus = "unverified-source-field" }
quests[47001] = { id = 47001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rare Elite 21" }
quests[47002] = { id = 47002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone des Triumvirats", description = "Wir werden jetzt mit der Suche beginnen, {name}.\n\nDie Krone des Triumvirats wurde geschaffen, um allen die Berührung des Lichts zu bringen. So gedieh unsere Kultur.\n\nAls ich mit den Draenei von Argus fliehen musste, nahm ich einen Splitter der Krone mit mir, damit er nicht in falsche Hände fallen konnte.\n\n<Velen neigt seinen Stab nach vorn und deutet auf den Kristall in der Mitte.>\n\nDie Fragmente von Kil'jaeden und Archimonde sind immer noch hier. Ich werde sie ausfindig machen, aber Ihr müsst mich bei der Suche beschützen.\n\nBleibt in meiner Nähe, <Freund/Freundin>.", sourceObjective = "Beschützt Velen, während er die Fragmente der Krone des Triumvirats ausfindig macht.", sourceObjectiveStatus = "unverified-source-field" }
quests[47003] = { id = 47003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederherstellung: Die Untersuchung von Bradenbach", description = "Wir haben an der Küste gefälschte Befehle entdeckt. Sie weisen einen dämonischen Einfluss auf. Er lässt den Leser an ihre Rechtmäßigkeit glauben. Den Befehlen zufolge soll die Rabenwehr eine \"dämonische Enklave\" südlich ihrer Mauern angreifen. Dabei kann es sich nur um eine Enklave handeln: Bradenbach!\n\nKönnte es sein, dass dies die Untoten dazu treiben soll, Bradenbach anzugreifen? Ihr solltet Euch sofort dorthin begeben und sie entweder warnen oder ihnen Unterstützung anbieten.", sourceObjective = "Begebt Euch nach Bradenbach in Val'sharah.", completion = "Ein wenig spät für eine Warnung, oder? Dennoch freut es uns, dass man uns noch nicht ganz vergessen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[47004] = { id = 47004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederherstellung: Die Untersuchung von Bradenbach", description = "Wir haben an der Küste gefälschte Befehle entdeckt. Sie weisen einen dämonischen Einfluss auf. Er lässt den Leser an ihre Rechtmäßigkeit glauben. Den Befehlen zufolge soll die Rabenwehr eine \"dämonische Enklave\" südlich ihrer Mauern angreifen. Dabei kann es sich nur um eine Enklave handeln: Bradenbach!\n\nKönnte es sein, dass dies die Untoten dazu treiben soll, Bradenbach anzugreifen? Ihr solltet Euch sofort dorthin begeben und sie entweder warnen oder ihnen Unterstützung anbieten.", sourceObjective = "Begebt Euch nach Bradenbach in Val'sharah.", completion = "Ein wenig spät für eine Warnung, oder? Dennoch freut es uns, dass man uns noch nicht ganz vergessen hat.", sourceObjectiveStatus = "unverified-source-field" }
