quests[47017] = { id = 47017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur das Beste", sourceObjective = "Unsere Händler an der Frontlinie haben einige unfassbar seltene Gegenstände in ihren Besitz bringen können. Bitte setzt sie mit Bedacht ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[47018] = { id = 47018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tierherrschaft: Gepolter nahe Teufelstotem", description = "Die Tauren vom Hochbergstamm haben eine dringende Warnung übermittelt, die von ihren Verbündeten, den Drogbar, stammt. Die Teufelstotems verbreiten dämonische Verderbnis unter den Wildtieren in ihrer Umgebung und infizieren auch das Land selbst. Wir glauben, dass man dieser Sache lieber früher als später nachgehen sollte.\n\nDer Drogbarhäuptling Navarrogg kümmert sich persönlich darum und wir möchten, dass Ihr Euch mit ihm in der Nähe des Dorfs der Teufelstotems trefft.", sourceObjective = "Sucht Navarrogg am Nebelufer am Hochberg auf.", completion = "Ich danke Euch für Euer Kommen. Ich bin froh, dass Ihr diese Bedrohung ernst nehmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[47019] = { id = 47019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windläufer: Gepolter nahe Teufelstotem", description = "Die Tauren vom Hochbergstamm haben eine dringende Warnung übermittelt, die von ihren Verbündeten, den Drogbar, stammt. Die Teufelstotems verbreiten dämonische Verderbnis unter den Wildtieren in ihrer Umgebung und infizieren auch das Land selbst. Wir glauben, dass man dieser Sache lieber früher als später nachgehen sollte.\n\nDer Drogbarhäuptling Navarrogg kümmert sich persönlich darum und wir möchten, dass Ihr Euch mit ihm in der Nähe des Dorfs der Teufelstotems trefft.", sourceObjective = "Sucht Navarrogg am Nebelufer am Hochberg auf.", completion = "Ich danke Euch für Euer Kommen. Ich bin froh, dass Ihr diese Bedrohung ernst nehmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[47020] = { id = 47020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disziplin: Gepolter nahe Teufelstotem", description = "Die Tauren vom Hochbergstamm haben eine dringende Warnung übermittelt, die von ihren Verbündeten, den Drogbar, stammt. Die Teufelstotems verbreiten dämonische Verderbnis unter den Wildtieren in ihrer Umgebung und infizieren auch das Land selbst. Wir glauben, dass man dieser Sache lieber früher als später nachgehen sollte.\n\nDer Drogbarhäuptling Navarrogg kümmert sich persönlich darum und wir möchten, dass Ihr Euch mit ihm in der Nähe des Dorfs der Teufelstotems trefft.", sourceObjective = "Sucht Navarrogg am Nebelufer am Hochberg auf.", completion = "Ich danke Euch für Euer Kommen. Ich bin froh, dass Ihr diese Bedrohung ernst nehmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[47021] = { id = 47021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.2 Broken Shore - Buildings - Command Center - Buff - Follower Token - Tracking" }
quests[47022] = { id = 47022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schutz: Hilfe durch die Illidari", description = "Zum Glück sind wir nicht die Einzigen, die die Verschwörungen der Legion zur Infiltration der Stadt aufdecken.\n\nKor'vas Blutdorn von den Illidari hat begonnen, alleine die Straßen zu patrouillieren, um den Ursprung der jüngsten Angriffe aufzuspüren.\n\nSo ganz traue ich diesen \"Dämonenjägern\" nicht über den Weg, aber immerhin haben sie ihrem Namen alle Ehre gemacht. Ich schlage vor, Ihr sucht sie auf und seht, was sie herausgefunden hat, bevor die Legion erneut zuschlägt.", sourceObjective = "Findet Kor'vas Blutdorn in den Straßen von Dalaran.", completion = "Ihr... Euch habe ich doch draußen auf den Inseln gesehen.\n\nWir müssen uns beeilen!", sourceObjectiveStatus = "unverified-source-field" }
quests[47023] = { id = 47023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wächter: Hilfe durch die Illidari", description = "Zum Glück sind wir nicht die Einzigen, die die Verschwörungen der Legion zur Infiltration der Stadt aufdecken.\n\nKor'vas Blutdorn von den Illidari hat begonnen, alleine die Straßen zu patrouillieren, um den Ursprung der jüngsten Angriffe aufzuspüren.\n\nSo ganz traue ich diesen \"Dämonenjägern\" nicht über den Weg, aber immerhin haben sie ihrem Namen alle Ehre gemacht. Ich schlage vor, Ihr sucht sie auf und seht, was sie herausgefunden hat, bevor die Legion erneut zuschlägt.", sourceObjective = "Findet Kor'vas Blutdorn in den Straßen von Dalaran.", completion = "Ihr... Euch habe ich doch draußen auf den Inseln gesehen.\n\nWir müssen uns beeilen!", sourceObjectiveStatus = "unverified-source-field" }
