quests[47025] = { id = 47025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut: Hilfe durch die Illidari", description = "Zum Glück sind wir nicht die Einzigen, die die Verschwörungen der Legion zur Infiltration der Stadt aufdecken.\n\nKor'vas Blutdorn von den Illidari hat begonnen, alleine die Straßen zu patrouillieren, um den Ursprung der jüngsten Angriffe aufzuspüren.\n\nSo ganz traue ich diesen \"Dämonenjägern\" nicht über den Weg, aber immerhin haben sie ihrem Namen alle Ehre gemacht. Ich schlage vor, Ihr sucht sie auf und seht, was sie herausgefunden hat, bevor die Legion erneut zuschlägt.", sourceObjective = "Findet Kor'vas Blutdorn in den Straßen von Dalaran.", completion = "Ihr... Euch habe ich doch draußen auf den Inseln gesehen.\n\nWir müssen uns beeilen!", sourceObjectiveStatus = "unverified-source-field" }
