quests[47027] = { id = 47027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legionsbedrohung: Val'sharah", description = "Es scheint, Ihr seid nun stark genug, um Euch mit einer weiteren Bedrohung durch die Legion zu beschäftigen. Der Rat wäre Euch sehr verbunden, wenn Ihr Euch schnellstmöglich mit Erzmagierin Modera in Dalaran unterhalten würdet.", sourceObjective = "Sprecht mit Erzmagierin Modera in Dalaran.", completion = "Danke, dass Ihr gekommen seid. Ich möchte Euch etwas zeigen.", sourceObjectiveStatus = "unverified-source-field" }
