quests[47030] = { id = 47030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legionsbedrohung: Infiltration von Dalaran", description = "Es scheint, Ihr seid nun stark genug, um Euch mit einer weiteren Bedrohung durch die Legion zu beschäftigen. Der Rat wäre Euch sehr verbunden, wenn Ihr Euch schnellstmöglich mit Erzmagier Ansirem in Dalaran unterhalten würdet.", sourceObjective = "Sprecht mit Erzmagier Ansirem in Dalaran.", completion = "Danke, dass Ihr gekommen seid. Ich möchte Euch etwas zeigen.", sourceObjectiveStatus = "unverified-source-field" }
