quests[47032] = { id = 47032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legionsbedrohung: Azshara", description = "Es scheint, Ihr seid nun stark genug, um Euch mit einer weiteren Bedrohung durch die Legion zu beschäftigen. Der Rat wäre Euch sehr verbunden, wenn Ihr Euch schnellstmöglich mit Erzmagier Kalec in Dalaran unterhalten würdet.", sourceObjective = "Sprecht mit Erzmagier Kalec in Dalaran.", completion = "Danke, dass Ihr gekommen seid. Ich möchte Euch etwas zeigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[47033] = { id = 47033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legionsbedrohung: Suramar", description = "Es scheint, Ihr seid nun stark genug, um Euch mit einer weiteren Bedrohung durch die Legion zu beschäftigen. Ich möchte, dass Ihr schnellstmöglich beim Rat der Sechs in Dalaran vorsprecht. Ich danke Euch.", sourceObjective = "Sprecht mit Erzmagier Khadgar in Dalaran.", completion = "Danke, dass Ihr gekommen seid. Ich möchte Euch etwas zeigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[47034] = { id = 47034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legionsbedrohung: Der Totenbeschwörer", description = "Es scheint, Ihr seid nun stark genug, um Euch mit einer weiteren Bedrohung durch die Legion zu beschäftigen. Ich möchte, dass Ihr Euch schnellstmöglich mit Erzmagier Karlain trefft. Ich danke Euch.", sourceObjective = "Sprecht mit Erzmagier Karlain in Dalaran.", completion = "Danke, dass Ihr gekommen seid. Ich möchte Euch etwas zeigen.", sourceObjectiveStatus = "unverified-source-field" }
