quests[47036] = { id = 47036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rare Elite 24" }
quests[47037] = { id = 47037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gleichgewicht: Der zwistige Zwilling", description = "Ein alter Freund von mir, Karam Magusspeer, hat mich bei der Suche nach seinem Bruder Raest um Hilfe gebeten. Karam befürchtet, dass Raest sich mit dunklen Mächten eingelassen hat, und will ihn aufhalten.\n\nRaest wurde einst bei den Kirin Tor ausgebildet, aber er war so versessen auf Macht, dass er sich den verbotenen Künsten der Totenbeschwörung zuwandte. Als man dies entdeckte, wurde er aus unserem Orden verbannt.\n\nSucht Karam im Zauberkasten auf und bietet ihm Eure Hilfe an.", sourceObjective = "Sucht Karam Magusspeer im Zauberkasten in Dalaran auf.", completion = "Ihr kommt von den Kirin Tor? Dann wollt Ihr mir also helfen, meinen Bruder zu finden?", sourceObjectiveStatus = "unverified-source-field" }
quests[47038] = { id = 47038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.2 Broken Shore - Buildings - Activation Buff - Nether Disruptor - Seal Your Fate - Day 1 - Tracking" }
quests[47039] = { id = 47039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treffsicherheit: Der zwistige Zwilling", description = "Ein alter Freund von mir, Karam Magusspeer, hat mich bei der Suche nach seinem Bruder Raest um Hilfe gebeten. Karam befürchtet, dass Raest sich mit dunklen Mächten eingelassen hat, und will ihn aufhalten.\n\nRaest wurde einst bei den Kirin Tor ausgebildet, aber er war so versessen auf Macht, dass er sich den verbotenen Künsten der Totenbeschwörung zuwandte. Als man dies entdeckte, wurde er aus unserem Orden verbannt.\n\nSucht Karam im Zauberkasten auf und bietet ihm Eure Hilfe an.", sourceObjective = "Sucht Karam Magusspeer im Zauberkasten in Dalaran auf.", completion = "Ihr kommt von den Kirin Tor? Dann wollt Ihr mir also helfen, meinen Bruder zu finden?", sourceObjectiveStatus = "unverified-source-field" }
quests[47040] = { id = 47040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besiegeltes Schicksal", sourceObjective = "Ich habe ihn meinem Willen unterworfen, seine Kraft entzogen und ein Siegel heraufbeschworen. Wollt Ihr es haben?", sourceObjectiveStatus = "unverified-source-field" }
quests[47041] = { id = 47041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebrechen: Der zwistige Zwilling", description = "Ein alter Freund von mir, Karam Magusspeer, hat mich bei der Suche nach seinem Bruder Raest um Hilfe gebeten. Karam befürchtet, dass Raest sich mit dunklen Mächten eingelassen hat, und will ihn aufhalten.\n\nRaest wurde einst bei den Kirin Tor ausgebildet, aber er war so versessen auf Macht, dass er sich den verbotenen Künsten der Totenbeschwörung zuwandte. Als man dies entdeckte, wurde er aus unserem Orden verbannt.\n\nSucht Karam im Zauberkasten auf und bietet ihm Eure Hilfe an.", sourceObjective = "Sucht Karam Magusspeer im Zauberkasten in Dalaran auf.", completion = "Ihr kommt von den Kirin Tor? Dann wollt Ihr mir also helfen, meinen Bruder zu finden?", sourceObjectiveStatus = "unverified-source-field" }
quests[47042] = { id = 47042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatten: Der zwistige Zwilling", description = "Ein alter Freund von mir, Karam Magusspeer, hat mich bei der Suche nach seinem Bruder Raest um Hilfe gebeten. Karam befürchtet, dass Raest sich mit dunklen Mächten eingelassen hat, und will ihn aufhalten.\n\nRaest wurde einst bei den Kirin Tor ausgebildet, aber er war so versessen auf Macht, dass er sich den verbotenen Künsten der Totenbeschwörung zuwandte. Als man dies entdeckte, wurde er aus unserem Orden verbannt.\n\nSucht Karam im Zauberkasten auf und bietet ihm Eure Hilfe an.", sourceObjective = "Sucht Karam Magusspeer im Zauberkasten in Dalaran auf.", completion = "Ihr kommt von den Kirin Tor? Dann wollt Ihr mir also helfen, meinen Bruder zu finden?", sourceObjectiveStatus = "unverified-source-field" }
quests[47043] = { id = 47043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verwüstung: Der diebische Lehrling", description = "Die fokussierende Iris wurde aus den Tresoren Dalarans gestohlen! Der Dieb muss über beträchtliche magische Fertigkeiten verfügen, aber wir konnten ihn nicht aufspüren.\n\nGlücklicherweise aber hat der Dieb ein Schreiben seines Meisters fallen gelassen, in dem dieser von seinen \"Lehrlingsen\" spricht. Ich kenne nur einen, der seine Lehrlinge so bezeichnet: Erzmagier Xylem.\n\nIch möchte, dass Ihr die Sache untersucht. In Azshara findet Ihr seinen Turm, wo er seine Lehrlinge unterrichtet. Begebt Euch dorthin und findet heraus, was Xylem vorhat.", sourceObjective = "Reist zu Xylems Turm am Bärenkopf in Azshara.", completion = "Jemand hat die fokussierende Iris gestohlen und Ihr glaubt, dass Xylem dahintersteckt? Das könnte stimmen.\n\nEs ist kein Geheimnis, dass der Erzmagier immer auf der Suche nach Artefakten ist. Nach der Entdeckung eines antiken Zauberfolianten in den Ruinen der Legashi ist Xylem allerdings etwas... seltsam geworden. Ich fürchte, dieser Zauberfoliant beraubt ihn seines Verstandes.\n\nIch kann ein Treffen mit dem Erzmagier arrangieren. Mit etwas Glück könnt Ihr die Iris ohne Blutvergießen zurückholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[47044] = { id = 47044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.2 Broken Shore - Buildings - Activation Buff - Nether Disruptor - Seal Your Fate - Day 2 - Tracking" }
quests[47045] = { id = 47045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weitere Fortschritte", sourceObjective = "Der Disruptor ist immer noch meinem Willen unterworfen! Ich werde unaufhaltsam sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[47046] = { id = 47046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frost: Der diebische Lehrling", description = "Die fokussierende Iris wurde aus den Tresoren Dalarans gestohlen! Der Dieb muss über beträchtliche magische Fertigkeiten verfügen, aber wir konnten ihn nicht aufspüren.\n\nGlücklicherweise aber hat der Dieb ein Schreiben seines Meisters fallen gelassen, in dem dieser von seinen \"Lehrlingsen\" spricht. Ich kenne nur einen, der seine Lehrlinge so bezeichnet: Erzmagier Xylem.\n\nIch möchte, dass Ihr die Sache untersucht. In Azshara findet Ihr seinen Turm, wo er seine Lehrlinge unterrichtet. Begebt Euch dorthin und findet heraus, was Xylem vorhat.", sourceObjective = "Reist zu Xylems Turm am Bärenkopf in Azshara.", completion = "Jemand hat die fokussierende Iris gestohlen und Ihr glaubt, dass Xylem dahintersteckt? Das könnte stimmen.\n\nEs ist kein Geheimnis, dass der Erzmagier immer auf der Suche nach Artefakten ist. Nach der Entdeckung eines antiken Zauberfolianten in den Ruinen der Legashi ist Xylem allerdings etwas... seltsam geworden. Ich fürchte, dieser Zauberfoliant beraubt ihn seines Verstandes.\n\nIch kann ein Treffen mit dem Erzmagier arrangieren. Mit etwas Glück könnt Ihr die Iris ohne Blutvergießen zurückholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[47047] = { id = 47047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überleben: Der diebische Lehrling", description = "Die fokussierende Iris wurde aus den Tresoren Dalarans gestohlen! Der Dieb muss über beträchtliche magische Fertigkeiten verfügen, aber wir konnten ihn nicht aufspüren.\n\nGlücklicherweise aber hat der Dieb ein Schreiben seines Meisters fallen gelassen, in dem dieser von seinen \"Lehrlingsen\" spricht. Ich kenne nur einen, der seine Lehrlinge so bezeichnet: Erzmagier Xylem.\n\nIch möchte, dass Ihr die Sache untersucht. In Azshara findet Ihr seinen Turm, wo er seine Lehrlinge unterrichtet. Begebt Euch dorthin und findet heraus, was Xylem vorhat.", sourceObjective = "Reist zu Xylems Turm am Bärenkopf in Azshara.", completion = "Jemand hat die fokussierende Iris gestohlen und Ihr glaubt, dass Xylem dahintersteckt? Das könnte stimmen.\n\nEs ist kein Geheimnis, dass der Erzmagier immer auf der Suche nach Artefakten ist. Nach der Entdeckung eines antiken Zauberfolianten in den Ruinen der Legashi ist Xylem allerdings etwas... seltsam geworden. Ich fürchte, dieser Zauberfoliant beraubt ihn seines Verstandes.\n\nIch kann ein Treffen mit dem Erzmagier arrangieren. Mit etwas Glück könnt Ihr die Iris ohne Blutvergießen zurückholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[47048] = { id = 47048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Täuschung: Der diebische Lehrling", description = "Die fokussierende Iris wurde aus den Tresoren Dalarans gestohlen! Der Dieb muss über beträchtliche magische Fertigkeiten verfügen, aber wir konnten ihn nicht aufspüren.\n\nGlücklicherweise aber hat der Dieb ein Schreiben seines Meisters fallen gelassen, in dem dieser von seinen \"Lehrlingsen\" spricht. Ich kenne nur einen, der seine Lehrlinge so bezeichnet: Erzmagier Xylem.\n\nIch möchte, dass Ihr die Sache untersucht. In Azshara findet Ihr seinen Turm, wo er seine Lehrlinge unterrichtet. Begebt Euch dorthin und findet heraus, was Xylem vorhat.", sourceObjective = "Reist zu Xylems Turm am Bärenkopf in Azshara.", completion = "Jemand hat die fokussierende Iris gestohlen und Ihr glaubt, dass Xylem dahintersteckt? Das könnte stimmen.\n\nEs ist kein Geheimnis, dass der Erzmagier immer auf der Suche nach Artefakten ist. Nach der Entdeckung eines antiken Zauberfolianten in den Ruinen der Legashi ist Xylem allerdings etwas... seltsam geworden. Ich fürchte, dieser Zauberfoliant beraubt ihn seines Verstandes.\n\nIch kann ein Treffen mit dem Erzmagier arrangieren. Mit etwas Glück könnt Ihr die Iris ohne Blutvergießen zurückholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[47049] = { id = 47049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonologie: Das Schicksal der Wellenskorn", description = "Gestern ist ein Kundschafter aus Sturmheim mit einer bedeutenden Entdeckung eingetroffen: diesen antiken Schriftrollen. Sie enthalten eine Prophezeiung der Valkyra über eine neue Anführerin der Vrykul... eine, die die Wellenskorn in den Kampf gegen die Legion führen könnte.\n\nWas die Sache kompliziert macht, ist die Tatsache, dass sie womöglich die Nachfahrin von Skovald ist.\n\nNehmt diese Schriftrollen, findet die Nachfahrin und bringt sie zu den Valkyra. Ich glaube, die in der Prophezeiung erwähnten Verbannten sind die Vrykul von Jandvik. Das wäre also ein guter Ausgangspunkt für Eure Suche.", sourceObjective = "Sucht Jandvik auf, um die in den Schriftrollen erwähnte Vrykul zu finden.", completion = "Und was habt Ihr hier zu suchen, Fremdling?", sourceObjectiveStatus = "unverified-source-field" }
quests[47050] = { id = 47050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkung: Das Schicksal der Wellenskorn", description = "Gestern ist ein Kundschafter aus Sturmheim mit einer bedeutenden Entdeckung eingetroffen: diesen antiken Schriftrollen. Sie enthalten eine Prophezeiung der Valkyra über eine neue Anführerin der Vrykul... eine, die die Wellenskorn in den Kampf gegen die Legion führen könnte.\n\nWas die Sache kompliziert macht, ist die Tatsache, dass sie womöglich die Nachfahrin von Skovald ist.\n\nNehmt diese Schriftrollen, findet die Nachfahrin und bringt sie zu den Valkyra. Ich glaube, die in der Prophezeiung erwähnten Verbannten sind die Vrykul von Jandvik. Das wäre also ein guter Ausgangspunkt für Eure Suche.", sourceObjective = "Sucht Jandvik auf, um die in den Schriftrollen erwähnte Vrykul zu finden.", completion = "Und was habt Ihr hier zu suchen, Fremdling?", sourceObjectiveStatus = "unverified-source-field" }
quests[47051] = { id = 47051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meucheln: Das Schicksal der Wellenskorn", description = "Gestern ist ein Kundschafter aus Sturmheim mit einer bedeutenden Entdeckung eingetroffen: diesen antiken Schriftrollen. Sie enthalten eine Prophezeiung der Valkyra über eine neue Anführerin der Vrykul... eine, die die Wellenskorn in den Kampf gegen die Legion führen könnte.\n\nWas die Sache kompliziert macht, ist die Tatsache, dass sie womöglich die Nachfahrin von Skovald ist.\n\nNehmt diese Schriftrollen, findet die Nachfahrin und bringt sie zu den Valkyra. Ich glaube, die in der Prophezeiung erwähnten Verbannten sind die Vrykul von Jandvik. Das wäre also ein guter Ausgangspunkt für Eure Suche.", sourceObjective = "Sucht Jandvik auf, um die in den Schriftrollen erwähnte Vrykul zu finden.", completion = "Und was habt Ihr hier zu suchen, Fremdling?", sourceObjectiveStatus = "unverified-source-field" }
quests[47052] = { id = 47052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergeltung: Das Schicksal der Wellenskorn", description = "Gestern ist ein Kundschafter aus Sturmheim mit einer bedeutenden Entdeckung eingetroffen: diesen antiken Schriftrollen. Sie enthalten eine Prophezeiung der Valkyra über eine neue Anführerin der Vrykul... eine, die die Wellenskorn in den Kampf gegen die Legion führen könnte.\n\nWas die Sache kompliziert macht, ist die Tatsache, dass sie womöglich die Nachfahrin von Skovald ist.\n\nNehmt diese Schriftrollen, findet die Nachfahrin und bringt sie zu den Valkyra. Ich glaube, die in der Prophezeiung erwähnten Verbannten sind die Vrykul von Jandvik. Das wäre also ein guter Ausgangspunkt für Eure Suche.", sourceObjective = "Sucht Jandvik auf, um die in den Schriftrollen erwähnte Vrykul zu finden.", completion = "Und was habt Ihr hier zu suchen, Fremdling?", sourceObjectiveStatus = "unverified-source-field" }
quests[47053] = { id = 47053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.2 Broken Shore - Buildings - Activation Buff - Nether Disruptor - Seal Your Fate - Day 3 - Tracking" }
quests[47054] = { id = 47054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schicksalsberührt", sourceObjective = "Ich... kann nicht mehr. Ich fürchte, ich bin zu weit gegangen. Hier, nehmt dieses letzte Siegel.", sourceObjectiveStatus = "unverified-source-field" }
quests[47055] = { id = 47055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuer: Die Torheit der Levia Laurence", description = "Levia Laurence war vor langer Zeit ein Mitglied der Kirin Tor. Als sie mit Schattenmagie herumexperimentierte, wurde sie aus der Stadt verbannt, aber sie kennt die Straßen zu genau, als dass man sie endgültig fernhalten könnte.\n\nLevia ist verschwunden und ich mache mir große Sorgen. Ihre Arbeit könnte die Aufmerksamkeit der Legion erregt haben. Das ist schon einmal geschehen. Es wäre sehr gefährlich, wenn ihr Wissen in die Hände der Legion geriete.\n\nZuletzt wurde sie im Sacellum der Schreiber gesehen. Fragt dort doch einmal nach und seht, ob Ihr eine Spur von ihr findet.", sourceObjective = "Fragt in der Stadt nach Informationen über Levia Laurence.", completion = "Es scheint, als ob Levia der Verführung eines Sukkubus verfallen ist. Ich fürchte, ihre Zeit als einsame Ausgestoßene hat sie wohl für derartige Winkelzüge empfänglich gemacht. Ich kann nicht umhin, mich irgendwie schuldig zu fühlen, dass sie diesen Weg eingeschlagen hat.\n\nJedenfalls befindet sich Levia in großer Gefahr. Sie muss gefunden werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[47056] = { id = 47056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Furor: Die Torheit der Levia Laurence", description = "Levia Laurence war vor langer Zeit ein Mitglied der Kirin Tor. Als sie mit Schattenmagie herumexperimentierte, wurde sie aus der Stadt verbannt, aber sie kennt die Straßen zu genau, als dass man sie endgültig fernhalten könnte.\n\nLevia ist verschwunden und ich mache mir große Sorgen. Ihre Arbeit könnte die Aufmerksamkeit der Legion erregt haben. Das ist schon einmal geschehen. Es wäre sehr gefährlich, wenn ihr Wissen in die Hände der Legion geriete.\n\nZuletzt wurde sie im Sacellum der Schreiber gesehen. Fragt dort doch einmal nach und seht, ob Ihr eine Spur von ihr findet.", sourceObjective = "Fragt in der Stadt nach Informationen über Levia Laurence.", completion = "Es scheint, als ob Levia der Verführung eines Sukkubus verfallen ist. Ich fürchte, ihre Zeit als einsame Ausgestoßene hat sie wohl für derartige Winkelzüge empfänglich gemacht. Ich kann nicht umhin, mich irgendwie schuldig zu fühlen, dass sie diesen Weg eingeschlagen hat.\n\nJedenfalls befindet sich Levia in großer Gefahr. Sie muss gefunden werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[47057] = { id = 47057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unheilig: Die Torheit der Levia Laurence", description = "Levia Laurence war vor langer Zeit ein Mitglied der Kirin Tor. Als sie mit Schattenmagie herumexperimentierte, wurde sie aus der Stadt verbannt, aber sie kennt die Straßen zu genau, als dass man sie endgültig fernhalten könnte.\n\nLevia ist verschwunden und ich mache mir große Sorgen. Ihre Arbeit könnte die Aufmerksamkeit der Legion erregt haben. Das ist schon einmal geschehen. Es wäre sehr gefährlich, wenn ihr Wissen in die Hände der Legion geriete.\n\nZuletzt wurde sie im Sacellum der Schreiber gesehen. Fragt dort doch einmal nach und seht, ob Ihr eine Spur von ihr findet.", sourceObjective = "Fragt in der Stadt nach Informationen über Levia Laurence.", progress = "Habt Ihr Hinweise auf Levias Verschwinden gefunden?", completion = "Es scheint, als ob Levia der Verführung eines Sukkubus verfallen ist. Ich fürchte, ihre Zeit als einsame Ausgestoßene hat sie wohl für derartige Winkelzüge empfänglich gemacht. Ich kann nicht umhin, mich irgendwie schuldig zu fühlen, dass sie diesen Weg eingeschlagen hat.\n\nJedenfalls befindet sich Levia in großer Gefahr. Sie muss gefunden werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[47058] = { id = 47058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesetzlosigkeit: Die Torheit der Levia Laurence", description = "Levia Laurence war vor langer Zeit ein Mitglied der Kirin Tor. Als sie mit Schattenmagie herumexperimentierte, wurde sie aus der Stadt verbannt, aber sie kennt die Straßen zu genau, als dass man sie endgültig fernhalten könnte.\n\nLevia ist verschwunden und ich mache mir große Sorgen. Ihre Arbeit könnte die Aufmerksamkeit der Legion erregt haben. Das ist schon einmal geschehen. Es wäre sehr gefährlich, wenn ihr Wissen in die Hände der Legion geriete.\n\nZuletzt wurde sie im Sacellum der Schreiber gesehen. Fragt dort doch einmal nach und seht, ob Ihr eine Spur von ihr findet.", sourceObjective = "Fragt in der Stadt nach Informationen über Levia Laurence.", completion = "Es scheint, als ob Levia der Verführung eines Sukkubus verfallen ist. Ich fürchte, ihre Zeit als einsame Ausgestoßene hat sie wohl für derartige Winkelzüge empfänglich gemacht. Ich kann nicht umhin, mich irgendwie schuldig zu fühlen, dass sie diesen Weg eingeschlagen hat.\n\nJedenfalls befindet sich Levia in großer Gefahr. Sie muss gefunden werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[47059] = { id = 47059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildheit: Die Torheit der Levia Laurence", description = "Levia Laurence war vor langer Zeit ein Mitglied der Kirin Tor. Als sie mit Schattenmagie herumexperimentierte, wurde sie aus der Stadt verbannt, aber sie kennt die Straßen zu genau, als dass man sie endgültig fernhalten könnte.\n\nLevia ist verschwunden und ich mache mir große Sorgen. Ihre Arbeit könnte die Aufmerksamkeit der Legion erregt haben. Das ist schon einmal geschehen. Es wäre sehr gefährlich, wenn ihr Wissen in die Hände der Legion geriete.\n\nZuletzt wurde sie im Sacellum der Schreiber gesehen. Fragt dort doch einmal nach und seht, ob Ihr eine Spur von ihr findet.", sourceObjective = "Fragt in der Stadt nach Informationen über Levia Laurence.", completion = "Es scheint, als ob Levia der Verführung eines Sukkubus verfallen ist. Ich fürchte, ihre Zeit als einsame Ausgestoßene hat sie wohl für derartige Winkelzüge empfänglich gemacht. Ich kann nicht umhin, mich irgendwie schuldig zu fühlen, dass sie diesen Weg eingeschlagen hat.\n\nJedenfalls befindet sich Levia in großer Gefahr. Sie muss gefunden werden!", sourceObjectiveStatus = "unverified-source-field" }
