quests[47066] = { id = 47066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Boden weihen", description = "Wir haben alles, was wir brauchen.\n\nIn der Nische unter uns findet Ihr die zerschmetterten Überreste der Argunitmatrix. Wenn der Schlüsselstein ersetzt ist, wird sie wieder voll einsatzfähig sein.\n\nDann werden alle Pylonen, die Ihr aktiviert habt, alle zurückschlagen können, die immer noch meine Leute jagen. Diese Schlacht wird endlich vorbei sein.\n\nIch hoffe, sie werden Frieden finden.", sourceObjective = "Repariert die Argunitmatrix unterhalb des Triumviratsbruchs.", completion = "<Velen starrt Euch besorgt an.>", sourceObjectiveStatus = "unverified-source-field" }
quests[47067] = { id = 47067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach verlorenem Wissen", description = "Während des Angriffs haben unsere Streitkräfte einen uralten Folianten der Nachtelfen entdeckt. Dass dieser diese raue Umgebung so lange überstanden hat, ist bemerkenswert.\n\nDie Verzauberungen haben mit der Zeit an Kraft eingebüßt, aber ich spüre, dass das Buch... geradezu hungrig ist, als ob es dorthin streben würde, wo die Elfen vor langer Zeit Magie praktiziert haben.\n\nWenn Ihr den Folianten zu den Ruinen in der Nähe bringt, lernen wir womöglich Geheimnisse, die uns einen Vorteil gegenüber der Legion verschaffen.", sourceObjective = "Benutzt den Folianten bei einigen Nachtelfenruinen an der Verheerten Küste.", completion = "Dieser Foliant ist faszinierend! Er scheint jegliches Wissen, das er nicht bereits enthält, aktiv zu suchen.\n\nEin erfahrener Forscher könnte ihn bestimmt darauf ansetzen, bestimmtes Wissen zu finden.\n\nHmm, da kommt mir eine Idee...", sourceObjectiveStatus = "unverified-source-field" }
quests[47068] = { id = 47068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rare Elite 25" }
quests[47069] = { id = 47069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung verlorenen Wissens", description = "Es liegt im Wesen dieses uralten Folianten der Nachtelfen, neues Wissen zu suchen. Das könnte für die Erforschung Eurer Artefaktwaffe von großem Wert sein.\n\nDie Gelehrten in Eurer Ordenshalle würden bestimmt großen Nutzen aus ihm ziehen und womöglich neue Wege der Macht erschließen.\n\nIch würde vorschlagen, dass Ihr ihn sofort zu ihnen bringt. Im Kampf gegen die Legion können wir jeden Vorteil gebrauchen!", sourceObjective = "Sprecht mit dem Artefaktforscher in Eurer Klassenordenshalle.", completion = "Was habt Ihr heute mitgebracht, Großmeister?\n\n<Cho untersucht den uralten Folianten.>\n\nDieses Buch ändert alles!", sourceObjectiveStatus = "unverified-source-field" }
quests[47070] = { id = 47070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung verlorenen Wissens", description = "Es liegt im Wesen dieses uralten Folianten der Nachtelfen, neues Wissen zu suchen. Das könnte für die Erforschung Eurer Artefaktwaffe von großem Wert sein.\n\nDie Gelehrten in Eurer Ordenshalle würden bestimmt großen Nutzen aus ihm ziehen und womöglich neue Wege der Macht erschließen.\n\nIch würde vorschlagen, dass Ihr ihn sofort zu ihnen bringt. Im Kampf gegen die Legion können wir jeden Vorteil gebrauchen!", sourceObjective = "Sprecht mit dem Artefaktforscher in Eurer Klassenordenshalle.", completion = "Was habt Ihr heute mitgebracht, Erzmagier?\n\n<Edirah untersucht den uralten Folianten.>\n\nDieses Buch ändert alles!", sourceObjectiveStatus = "unverified-source-field" }
