quests[47096] = { id = 47096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Choice: Blacksmithing" }
quests[47097] = { id = 47097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erinnerungswürdige Eindrücke", description = "Es ist gut, Euch an meiner Seite zu wissen, {name}.\n\nIch bin zur Verheerten Küste gekommen, um den Preis, den mein Vater... den die Allianz zum Schutz unserer Welt gezahlt hat, mit eigenen Augen zu sehen.\n\nWenn ich blind gegenüber den Leiden und Opfern meines Volkes bin, werde ich ihm niemals Frieden bringen können.\n\nWir haben nicht viel Zeit. Wir müssen weiter.", sourceObjective = "Eskortiert König Anduin zum Seelentrümmerfeld an der Verheerten Küste.", completion = "Dieser Ort ist voller unbeschreiblicher Schrecken. Kaum zu glauben, dass... ich so blind gegenüber all den Leiden und Schmerzen war.", sourceObjectiveStatus = "unverified-source-field" }
quests[47098] = { id = 47098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf und davon mit Finn", description = "Ich bin ja so erleichtert, dass Ihr aufgewacht seid. Euch hier rauszutragen, hätte wohl einige Unannehmlichkeiten mehr bedeutet.\n\nMein Name ist Finn und mein Klient in Boralus zahlt mir eine fürstliche Prämie dafür, Euch hier rauszuholen.\n\nIhr seid hier in Tol Dagor eingekerkert, <mein Freund/meine Liebe>. Früher war das ein anständiges Gefängnis, bis die Handelskompanie Aschenwind es gekauft hat. Jetzt ist es Priscillas Privatgefängnis voller Gesindel auf beiden Seiten der Gitter.\n\nAndererseits war es dadurch auch nicht gerade schwer, die Wärter zu bestechen, um zu Euch zu kommen. Jetzt müssen wir nur noch einen Weg hinaus finden.\n\nAber sorgt Euch nicht, ich habe schon einen Plan!", sourceObjective = "Flieht mit Finn aus Tol Dagor.", progress = "Ist das das neue Pulver, von dem Finn gesprochen hat?\n\nIch nehme es sicherheitshalber mal an mich.", completion = "Es ist schwer zu glauben, dass die Lordadmiralin Euch und ihre Tochter einfach so an Lady Aschenwind ausliefert.\n\nSie hat mit Sicherheit ihre Gründe, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[47099] = { id = 47099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orientierungslauf", description = "Ich glaube, jetzt ist es angebracht, sich richtig vorzustellen!\n\nIch heiße Taelia, gehöre der Prachtmeerwache an und bin Knappin von Sir Carsten Jammerthal.\n\n<Taelia salutiert zackig.>\n\nCarsten hat mich und Finn gebeten, Euch aus dem Aschenwindgefängnis herauszuholen und dafür zu sorgen, dass Ihr Euch hier auf dem Markt einlebt. Allerdings hat er vergessen zu erwähnen, dass Ihr der Allianz angehört.\n\nIch muss sagen, es ist mir eine Ehre.\n\nBringen wir Euch auf den aktuellen Stand.", sourceObjective = "Besucht den Fährhafen, die Hafenstube, das Zählhaus des Handelswindmarkts und den Flugmeister auf dem Handelswindmarkt.", progress = "Ich bringe Euch zu Carsten, nachdem ich Euch schnell den Markt gezeigt habe.", completion = "Seid Ihr bereit, den Hafenmeister höchst persönlich zu treffen?", sourceObjectiveStatus = "unverified-source-field" }
quests[47100] = { id = 47100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkhaans Leid", description = "Die Dunkelheit umgibt uns... das Licht hat diesen Ort verlassen...\n\n<Arkhaan murmelt vor sich hin, bevor er bemerkt, dass Ihr noch immer mit ihm sprecht.>\n\nArkhaan konnte sie nicht retten. Brüder. Schwestern. Vom Flüstern entstellt. Das Licht kann sie nicht sehen. Es wendet sich von uns ab.\n\nArkhaan hat versagt.\n\n<Arkhaan starrt ins Nichts.>", sourceObjective = "Tötet 12 Zerschlagene im Oronaareinsturz.", completion = "<Der Zerschlagene sieht sich nervös um und vermeidet jeglichen Augenkontakt mit Euch.>", sourceObjectiveStatus = "unverified-source-field" }
quests[47101] = { id = 47101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkhaans Gebete", description = "<Als Ihr Euch der Statue nähert, durchdringt eine sonore Stimme Euren Geist.>\n\n\"Ihr müsst Euch dem Sog des Schattens entziehen. Kommt zu mir, Brüder und Schwestern. Werdet eins mit dem Licht.\n\nLasst Euch von Arkhaan den Weg nach Hause zeigen.\"\n\n<Der Rest der Nachricht ist unverständlich, während die Zerschlagenen in der Nähe auf Teilen der Statue herumzukauen scheinen.>", sourceObjective = "Sammelt 5 Gebetsfragmente.", progress = "Habt Ihr etwas Interessantes gefunden?", completion = "Was ist das? Eine Predigt? Faszinierend.", sourceObjectiveStatus = "unverified-source-field" }
quests[47102] = { id = 47102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das mysteriöse Schreiben", description = "<Bei der Leiche findet Ihr ein mit dem Siegel der Armee des Lichts versehenes Schreiben.\n\nWenn der Bote getötet wurde, um die Auslieferung des Schreibens zu verhindern, muss der Inhalt entsprechend bedeutsam sein.>", sourceObjective = "Sucht in der Nähe der Xenedar nach jemandem, der über das versiegelte Schreiben Bescheid weiß.", progress = "Unser Kampf geht weiter, Champion. Argus muss fallen.\n\nWas habt Ihr gefunden?", completion = "Ihr habt einen unserer Späherberichte gefunden? Er war schon überfällig und ich dachte, er wäre den Feinden in die Hände gefallen.\n\n<Der Hauptmann schaut sich das Schreiben an.>\n\nJa, das hatte ich erwartet. Die Legion führt irgendetwas im Schilde und das ist der Durchbruch, auf den wir gewartet haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[47103] = { id = 47103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise nach Nazmir", description = "Wir müss'n den Bluttrollen in Nazmir endlich 'n Ende bereiten, bevor sie mit ihrer monströsen Horde Zuldazar überfall'n!\n\nMeine treusten Gefährten sind bereit, mich zu diesem verflucht'n Ort zu begleiten. Aber das wird nich' reich'n.\n\nIch bin erleichtert, dass Ihr un' die Horde helf'n wollt. Rokhan und seine Dunkelspeere bereiten sich vor, aufzubrechen.\n\nIch werd hier meine Vorbereitungen abschließ'n. Trefft Euch mit Rokhan un' brecht nach Nazmir auf. Wir seh'n uns dort.", sourceObjective = "Trefft Euch mit Rokhan bei Flugmeisterin Rokota in Dazar'alor.", completion = "{name}! Seid Ihr bereit, 'nen verfluchten Sumpf zu betreten?", sourceObjectiveStatus = "unverified-source-field" }
quests[47104] = { id = 47104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eingesperrter Inquisitor", description = "Im Bericht steht, dass die Legion einen gefangenen Legionsinquisitor namens Raalgar befreien will, einen Dämon, der hier von Argus stammt und aufgrund einer geheimen Magie, über die nur er verfügt, nicht getötet werden kann.\n\nAufgrund seiner Unsterblichkeit wird er in der Arkatraz in der Festung der Stürme gefangen gehalten.\n\nDie Lichtmutter hat uns von der Naarufestung erzählt, aber ich habe sie nie mit eigenen Augen gesehen, {name}. Turalyon erwähnte, dass es eine Verbindung zwischen der Vindikaar und der Festung der Stürme gibt. Vielleicht weiß Euer Schiffsingenieur mehr darüber.", sourceObjective = "Reist zur Vindikaar und befragt Großkonstrukteur Romuul zu Hochinquisitor Raalgar.", completion = "Hochinquisitor Raalgar? Er ist eine furchterregende Gestalt, aber er befindet sich seit langer Zeit in sicherem Gewahrsam, und zwar in der Arkatraz in der Festung der Stürme.\n\nWenn die Legion plant, ihn zu befreien, wird sie wohl wissen, wie gefährlich er für uns sein könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[47105] = { id = 47105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Finsternis", description = "Wir sin' in Nazmir, um die Bluttrolle davon abzuhalt'n, Zuldazar zu zerstör'n. Das is' der Anfang unsres Feldzugs, um sie auszulösch'n.\n\nDiese Monster woll'n mein Königreich un' sein Volk vernicht'n, also werd'n wir sie zuerst vernicht'n.\n\nMein Vater glaubt, dass die Bedrohung durch die Bluttrolle von selbst verschwind'n wird, so wie früher auch. Aber heute is' alles anders.\n\nRokhan un' die andren geh'n nach Norden un' schlagen dort 'n Lager für uns auf, dann werd'n sie sich uns im Kampf anschließ'n.\n\nSeid Ihr bereit?", sourceObjective = "Geht voraus und sucht mit Prinzessin Talanji nach Hinweisen auf Bluttrolle.", completion = "Die Bluttrolle sin' Monster, {name}. Sie sind überall um uns rum. Wir werden sie heute aufhalt'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[47106] = { id = 47106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.2 Raid - Tomb - 1 - Quest Item Reward - Tracking Quest" }
