quests[47112] = { id = 47112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlorene Seelen", description = "Derartige Verwüstung... ein derartiges Elend habe ich mein ganzes Leben noch nicht gesehen. Der Boden unter unseren Füßen ist bedeckt mit den Knochen unserer Verbündeten.\n\nSelbst jetzt sehe ich die verlorenen Geister der Soldaten der Allianz, wie sie durch die Ruinen irren.\n\nIch kann hier nicht fortgehen, ohne die Seelen unserer tapferen Soldaten zur Ruhe zu betten. So viel sind wir... so viel bin ich ihnen schuldig.", sourceObjective = "Befreit 10 verlorene Seelen.", completion = "Danke, {name}. Denjenigen, die das höchste Opfer für die Allianz und für Azeroth gebracht haben, können wir nur noch friedvolle Ruhe schenken.", sourceObjectiveStatus = "unverified-source-field" }
quests[47114] = { id = 47114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Grabmal des Sargeras: Die Herrin des Grabs", description = "Tötet die Nagaherrin, die die Meeresbewohner unterhalb des Grabmals verdirbt.", sourceObjective = "Besiegt Herrin Sassz'ine im Grabmal des Sargeras.", progress = "Wie gestalten sich die Herausforderungen im Grabmal des Sargeras?", completion = "Habt Ihr das Grabmal des Sargeras bewältigt?", sourceObjectiveStatus = "unverified-source-field" }
