quests[47126] = { id = 47126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Grabmal des Sargeras: Der Betrüger", description = "Nur die mächtigsten seiner Diener dürfen dieses Siegel tragen. Es offenbart die Anwesenheit des Betrügers, Kil'jaeden. Wir müssen ihn besiegen.", sourceObjective = "Besiegt Kil'jaeden im Grabmal des Sargeras.", progress = "Wie gestalten sich die Herausforderungen im Grabmal des Sargeras?", completion = "Habt Ihr das Grabmal des Sargeras bewältigt?", sourceObjectiveStatus = "unverified-source-field" }
