quests[47129] = { id = 47129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Grabmal des Sargeras: Der Betrüger", description = "Nur die mächtigsten seiner Diener dürfen dieses Siegel tragen. Es offenbart die Anwesenheit des Betrügers, Kil'jaeden. Wir müssen ihn besiegen.", sourceObjective = "Besiegt Kil'jaeden im Grabmal des Sargeras.", progress = "Wie gestalten sich die Herausforderungen im Grabmal des Sargeras?", completion = "Habt Ihr das Grabmal des Sargeras bewältigt?", sourceObjectiveStatus = "unverified-source-field" }
quests[47130] = { id = 47130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unangemessenes Begräbnis", description = "Die Bluttrolle sammeln die Leichen meiner Leute, um sie für ihre Blutmagie zu benutz'n. Damit is' ab heute Schluss.\n\nIch werd mich um die Leichen hier kümmern. Nehmt diese Fackel. Ihr Feuer is' von den Priestern von Bwonsamdi, dem Loa des Todes, gesegnet word'n.\n\nVerbrennt alle Leichen meiner Leute, die Ihr findet. Jeder verbrannte Leichnam bedeutet auch weniger Macht für die Blutmagie dieser Monster.", sourceObjective = "Nehmt die Zeremonienfackel und verbrennt die Leichen der Zandalari.", completion = "Meine Leute verdien' was Bessres als das hier. Wenn das hier vorbei is', müssen wir sie in Zuldazar gebührend ehr'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[47132] = { id = 47132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsfeuer und Eis" }
quests[47133] = { id = 47133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rare Mob Daily Bonus" }
quests[47134] = { id = 47134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefängnisausbruch der Legion vereiteln", description = "Hochinquisitor Raalgar scheint mit den teuflischen Mächten hier auf Argus so verbunden zu sein, dass man ihn nicht töten kann. Vor langer Zeit haben die Naaru ihn auf der Arkatraz eingesperrt.\n\nAls die Truppen von Kael'thas Sonnenwanderer die Zitadelle angriffen, mussten wir auf der Exodar fliehen.\n\nZwar konnten einige Gefangene von der Legion bei ihrer letzten Invasion auf Azeroth von der Arkatraz entkommen, aber Raalgar gehörte nicht dazu. Verhindert, dass sie ihn befreien, während ich die Quelle seiner Unsterblichkeit erforsche.\n\nIch kann Euch nahe heranbringen. Ab dann seid Ihr auf Euch selbst gestellt.", sourceObjective = "Findet Hochinquisitor Raalgar, bevor die Legion ihn befreien kann.", completion = "Ihr habt getan, was Ihr konntet, {name}, aber diese Runde haben die Dämonen gewonnen.\n\nEs wird nicht lange dauern, bis Raalgar stark genug ist, uns anzugreifen. Aber ich habe in Eurer Abwesenheit die Quelle seiner Unsterblichkeit entdeckt!", sourceObjectiveStatus = "unverified-source-field" }
quests[47135] = { id = 47135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu ihrem eigenen Besten" }
quests[47137] = { id = 47137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champions der Legionsrichter", description = "Der Kampf um die Verheerte Küste zehrt an unseren Ressourcen. Wir können uns keine Verschnaufpause leisten, sonst macht die Legion alle unsere Erfolge zunichte.\n\nDie Mitglieder Eures Ordens haben viel gegeben, doch wir brauchen noch mehr.\n\nVersammelt Eure Champions und tut, was nötig ist, um ihre Reihen zu stärken. Womöglich ruhen nicht genutzte Kräfte in diesem Land, die das Blatt zu unseren Gunsten wenden könnten.", sourceObjective = "Kehrt in Eure Klassenordenshalle zurück und rekrutiert einen neuen Champion.", completion = "Ein weiterer mächtiger Verbündeter für unsere Sache!\n\nWieder einmal habt Ihr uns im Kampf gegen die Legion stärker gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[47139] = { id = 47139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mal der Sentinax", description = "Die Sentinax terrorisiert die Verheerte Küste und lässt Horden von Dämonen auf unsere Streitkräfte los. Diese Bestien wollen verhindern, dass wir das Grabmal einnehmen.\n\nSie werden scheitern.\n\nLockt die stärksten aus ihren Reihen hervor und nehmt ihnen ihre Marken ab. Sorgt dafür, dass die Legion unsere Stärke fürchtet!", sourceObjective = "Sammelt 50 Male der Sentinax ein.", progress = "Die Sentinax ist gut geschützt, aber wir werden alles zerschmettern, was sie uns entgegenwirft.", completion = "Selbst die mächtigsten Dämonen, die die Sentinax entfesselt hat, sind durch Eure Hand umgekommen.\n\nGut. Wir werden die Legion aus unserer Welt vertreiben, koste es, was es wolle.", sourceObjectiveStatus = "unverified-source-field" }
quests[47144] = { id = 47144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Win of the Day (BG Brawl)" }
quests[47148] = { id = 47148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mal was anderes", description = "Selbst die blutrünstigsten Kämpfer werden irgendwann müde und wenden sich von den unendlichen Mühen des Krieges ab. Sie suchen nach neuen Wegen, ihre Entschlossenheit unter Beweis zu stellen und ihre Feinde zu vernichten.\n\nWerft Euch in die laufende Schlacht und bekämpft Eure Gegner in einem zeitlich begrenzten Ereignis, das die traditionellen Regeln komplett außer Acht lässt.", sourceObjective = "Gewinnt eine PvP-Rauferei.", completion = "Das habe selbst ich nicht kommen sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[47149] = { id = 47149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legion Season 3 and 4 - Gladiator's Plate Armor" }
