quests[47179] = { id = 47179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tier 3 Mob Weekly Bonus" }
quests[47180] = { id = 47180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pulsierender Wahnsinn", description = "Dieser Zerschlagene scheint noch über einen Teil seines Verstandes zu verfügen.\n\nIch kann den Einfluss der Leere in der Nähe spüren, aber sie hat sich in kleine Nischen zurückgezogen. Wenn wir diese Manifestationen auslöschen, könnten wir unserem Freund hier helfen, seinen Verstand zurückzugewinnen.\n\nVielleicht können wir ja die Gebetsfragmente verwenden, die Ihr gefunden habt. Sie enthalten immer noch etwas Lichtenergie.\n\nIch werde derweil versuchen, seinem Gestammel einen Sinn zu entlocken. Vielleicht erfahren wir ja, was hier vor sich geht.", sourceObjective = "Beseitigt 5 Manifestationen der Leere.", progress = "Seine Anwesenheit wirft mehr Fragen auf, als sie beantwortet.", completion = "Ich spüre, dass der Einfluss der Leere geringer wird. Vielleicht können wir jetzt herausfinden, was hier geschehen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[47181] = { id = 47181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein durchschlagender Beweis", description = "Die von Aschenwind & Co. wissen es noch nicht, aber dass sie Euch nach Tol Dagor verfrachtet haben, war der größte Fehler, den sie je begangen haben.\n\nDas neue Pulver, das wir uns besorgt haben, könnte der Schlüssel zu ihrem Untergang sein.\n\nAls Erstes sollten wir ihnen eine kleine Demonstration geben, wie mächtig dieses Zeug ist.\n\n<Finn lädt eine Prise von dem glitzernden Pulver in seine Pistole.>\n\nLos, schießt auf das Fass da drüben.", sourceObjective = "Feuert Finns Pistole auf das Wasserfass im Büro des Hafenmeisters ab.", progress = "Keine Sorge, das wird niemandem wehtun.\n\nGlaube ich.", completion = "Das macht richtig Spaß, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[47182] = { id = 47182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lange überfällig", description = "Ich habe vieles herausgefunden. Hochinquisitor Raalgar befindet sich mittlerweile in einer Legionszitadelle auf der anderen Seite der Berge. Dort verwahrt er das Teufelsherz von Argus, die Quelle seiner Unsterblichkeit. Es wird von Brunnen genährt, die direkt zum Kern von Argus reichen.\n\nEr bereitet zur Stunde seinen Angriff vor, also müsst Ihr zuerst zuschlagen. Markiert die Standorte der Brunnen, damit ich sie mit heiligem Feuer aus den Geschützen der Vindikaar eindecken kann. Wenn diese Verbindung zur Teufelsenergie von Argus unterbrochen ist, kann Raalgar getötet und das Teufelsherz sichergestellt werden.", sourceObjective = "Markiert die Herzbrunnen von Argus für die Geschütze der Vindikaar, vernichtet die Legionsgarnison und nehmt Hochinquisitor Raalgar das Teufelsherz von Argus ab.", progress = "Habt Ihr Euch schon um Hochinquisitor Raalgar gekümmert?", completion = "Ihr seid ein wahrer Held, {name}. Selbst nachdem Raalgar von den Dämonen befreit und für unsterblich gehalten wurde, hatte er keine Chance gegen Euch! Vielleicht habt Ihr Verwendung für das Teufelsherz. Es ist jetzt im Matrixkern verfügbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[47183] = { id = 47183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkhaans Plan", description = "Arkhaan erinnert sich. Er erinnert sich an etwas, das... ja... das uns retten wird.\n\nFolgt Arkhaan. Isolon ruft! Wir werden dem Licht sanfte Worte anbieten. Das Licht wird die Dunkelheit verbannen.\n\n<Arkhaan schaut Alleria argwöhnisch an.>\n\nArkhaan wird sie gut im Auge behalten.", sourceObjective = "Folgt Arkhaan nach Isolon.", completion = "Ich hätte es mir denken können.", sourceObjectiveStatus = "unverified-source-field" }
quests[47184] = { id = 47184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkhaans Verhängnis", description = "Welcher Stimme er auch immer folgen mag... sie wird nichts Gutes im Schilde führen. Wir müssen ihm hinterher.\n\nNoch eins, bevor wir durch dieses Portal gehen, {name}... Macht Euch auf einen Kampf gefasst. Der Einfluss der Leere ist selten friedvoller Natur.", sourceObjective = "Betretet den Leerenriss und kümmert Euch um Arkhaan.", completion = "Wie ich schon sagte: Der Einfluss der Leere ist selten friedvoller Natur. Wir müssen weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[47185] = { id = 47185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion Boss Weekly Bonus" }
quests[47186] = { id = 47186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Sanktum der Weisen", description = "Scheint mir, als würdet Ihr eine Weile mit uns zusammenarbeiten.\n\nCarsten wird eine Seetransportroute zwischen hier und Sturmwind einrichten, aber ich denke, für den täglichen Gebrauch wäre Euch etwas Schnelleres recht.\n\nLauft ganz nach oben und dann nach links, sobald Ihr draußen seid. Dort findet Ihr ein altes Studierzimmer, in dem die Gezeitenweisen immer ihre magischen Rituale durchgeführt haben.\n\nEure Allianzmagier haben sicher schon die besondere Energie wahrgenommen.\n\nSagt ihnen, dass sie dort ihre Portale öffnen können. Die Hafenwachen werden für die Sicherheit des Raums sorgen.", sourceObjective = "Sprecht mit einem Magier der 7. Legion im Sanktum der Weisen.", progress = "Die Gezeitenweisen haben diesen Ort vor Monaten verlassen und sich in ihre Klöster zurückgezogen. Wir wissen immer noch nicht, warum.", completion = "Alles fertig?\n\nPerfekt. Ich habe jetzt die Informationen für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[47188] = { id = 47188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hilfe der Loa", description = "Die Bluttrolle sin' stärker als je zuvor, dank dieses G'huun... Un' jetzt ermächtig'n sie auch noch 'n riesiges Konstrukt!\n\nWir brauch'n 'nen Plan, wie wir das Konstrukt, G'huun un' die Bluttrolle vernicht'n können. Das wird ganz un' gar nich' einfach.\n\nAber ich hab 'ne Idee.", sourceObjective = "Beratet Euch mit Talanji und Rokhan über Eure nächsten Schritte.", progress = "Wir hab'n viel zu besprech'n.", completion = "Die Hilfe der Loa is' vielleicht unsre einzige Chance, um die Bluttrolle aufzuhalt'n.\n\nAlso los.", sourceObjectiveStatus = "unverified-source-field" }
quests[47189] = { id = 47189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine gespaltene Nation", description = "Kul Tiras muss vereint werden, bevor es der Allianz auf irgendeine Weise nützlich sein kann.\n\nWir informieren Euch erst einmal über die aktuelle Lage in jedem unserer wichtigen Hoheitsgebiete.\n\nDann könnt Ihr einen Blick auf die Karte hinter mir werfen und entscheiden, wohin Ihr zuerst aufbrechen wollt.", sourceObjective = "Seht Euch die Späherkarte im Büro des Hafenmeisters an.", completion = "Wir unterstützen Euch, wo wir nur können.", sourceObjectiveStatus = "unverified-source-field" }
quests[47191] = { id = 47191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illusion - Demonic Tyranny" }
quests[47193] = { id = 47193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle for Azsuna" }
quests[47194] = { id = 47194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle for Highmountain" }
quests[47195] = { id = 47195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle for Stormheim" }
quests[47196] = { id = 47196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle for Val'sharah" }
quests[47198] = { id = 47198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie wollen uns lebend", description = "Bluttrollgifte soll'n Opfer paralysier'n un' nich' töten. Sie woll'n uns offensichtlich lebendig.\n\nDer Grund dafür bereitet mir ernsthafte Sorgen.\n\nIch arbeite so schnell ich kann am Gegengift, aber ich brauch wen wie Euch, der es für mich da draußen testet. Nehmt, was ich bereits hergestellt hab, un' versucht die Soldaten damit wieder auf die Beine zu bekomm'.", sourceObjective = "Heilt 8 verwundete Gefangene.", completion = "Es hat funktioniert? Gut! Ich werd einige Verwundete anweis'n, mir dabei zu helfen, mehr herzustell'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[47199] = { id = 47199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Bluttor", description = "Wir haben gerade erfahren, dass die nördliche Grenze schwer von einer Armee Bluttrolle bedrängt wird.\n\nKönig Rastakhan hat Verstärkung angefordert.\n\nMit dieser Bedrohung habt Ihr mehr Erfahrung als jeder andere von uns. Geht und helft ihnen, wo Ihr könnt.", sourceObjective = "Begebt Euch zum Bluttor.", completion = "Willkommen am Ende meines Reichs, und das gleich in mehrfacher Hinsicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[47200] = { id = 47200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zecken", description = "Tötet die Blutbäuche, bevor sie sich alle unsre Soldaten hol'n! Ich bereite mit meinen Truppen 'nen Flankenangriff vor.", sourceObjective = "Tötet 6 Blutbauchflügler.", completion = "Endlich 'n bisschen Platz zum Atmen. Wir müssen unseren Vorteil jetzt ausnutz'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[47201] = { id = 47201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rokhan", sourceObjective = "Reitet auf der alten Rotana in die Schlacht und findet dann Rokhan.", completion = "Ha! Ich dacht' schon, ich würd' bald Bwonsamdi persönlich kennenlernen. Aber nein.", sourceObjectiveStatus = "unverified-source-field" }
quests[47202] = { id = 47202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine persönliche Nachricht", description = "Es ist Zeit, dass ich zur Verheerten Küste reise und den Ort mit eigenen Augen sehe, an dem mein Vater gefallen ist.\n\nWenn ich ein König sein soll, wie mein Vater es war... und wie Sturmwind ihn verdient hat, dann muss ich am eigenen Leib erfahren, was mein Volk bedroht.\n\nBitte sagt meinen Beratern, dass ich an die Verheerte Küste gereist bin. Wenn ich ihnen das selbst mitteile, würden sie nur versuchen, mich aufzuhalten.\n\nIch erwarte Euch an der Retterklippe. Lebt wohl.", sourceObjective = "Sprecht mit Prophet Velen.", completion = "<Velen hört aufmerksam zu, während Ihr ihm König Anduins Plan schildert.>\n\nDie Verheerte Küste ist gefährlich... viel zu gefährlich, um dort allein unterwegs zu sein. Doch vielleicht braucht Anduin diese Reise, um seinen Frieden zu finden.\n\nWenn der richtige Zeitpunkt gekommen ist, werde ich König Graumähne Anduins Abreise melden. Seht Ihr bis dahin zu, dass Anduin an der Verheerten Küste nicht allein ist. Ich vertraue darauf, dass Ihr ihn uns heil zurückbringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[47203] = { id = 47203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatten werfen", description = "Das war der Raumgänger. Er hat mir alles, was ich über die Leere weiß, beigebracht. Und es gibt noch so viel mehr, das er mir zeigen kann.\n\nDass er hier ist, macht die Astralen umso interessanter für mich. Ich dachte, er wäre der Einzige seiner Art, aber jetzt habe ich gesehen, dass auch andere mit der Leere in Kontakt treten...\n\nKommt, wir müssen sein Spiel mitspielen, wenn wir erfahren wollen, was er weiß. Er scheint sich zur Umbralsenke im Norden aufgemacht zu haben.", sourceObjective = "Untersucht die Umbralsenke mit Alleria und dem Raumgänger.", completion = "<Alleria scheint kurzzeitig sprachlos zu sein.>", sourceObjectiveStatus = "unverified-source-field" }
quests[47204] = { id = 47204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die neue Frontlinie", description = "Tötet alle, die nich' wie Zandalari ausseh'n!", sourceObjective = "Schlachtet die Streitmacht der Bluttrolle ab.", completion = "Das sieht nach 'ner ganzen Menge aus, klar, aber glaubt mir, auf unsrem Weg hierher, ham wir noch viel mehr geseh'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[47205] = { id = 47205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsmatrone", description = "Die alte Rotana wurd von der Kriegsmatrone verflucht, die diese fiesen Bluttrolle mitgebracht ham. Wir müss'n sie ausschalten, damit wir das alte Terrorhorn wieder auf die Beine bring'n können.", sourceObjective = "Tötet Kriegsmatrone Shazraka.", completion = "Das verdammte Vieh hat 'n halbes Dutzend meiner Späher aufm Gewiss'n. Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[47207] = { id = 47207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
