quests[47214] = { id = 47214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[47215] = { id = 47215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[47217] = { id = 47217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quellen der Dunkelheit", description = "Ich glaube, ich weiß, was er uns zeigen wollte, {name}.\n\nIch spüre da vorn eine große Ansammlung von Kraft. Sie scheinen die Leere zu kultivieren und sie hierherzurufen.\n\nWir müssen sie aufhalten, bevor sie die ganze Stadt in die Schatten stürzen lassen. Findet die Quelle und kappt sie um jeden Preis.\n\nDer Raumgänger und ich haben noch eine Angelegenheit zu klären.", sourceObjective = "Deaktiviert 5 Leerenernter.", completion = "Damit kaufen wir uns Zeit, aber das ist auch alles.", sourceObjectiveStatus = "unverified-source-field" }
quests[47218] = { id = 47218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schattenwachenvorstoß", description = "Ihr habt sicherlich schon mitbekommen, dass ein Teil meiner Leute tragischerweise dem Ruf der Leere verfallen ist.\n\nIch hatte gehofft, mehr zu finden, die über die nötige Geistesstärke verfügen. Ich bin enttäuscht über diesen heillosen Mangel an Widerstandskraft.\n\nAber es lässt sich nicht ändern. Um Eure und meine Sache voranzutreiben, werden wir diese Gestalten schwachen Geistes auslöschen müssen.", sourceObjective = "Tötet 15 Astrale der Schattenwache.", progress = "Ein Ritt auf der Rasierklinge birgt Risiken, {name}.", completion = "Es ist gut zu wissen, dass wir ein gemeinsames Ziel haben. Vielleicht habe ich doch noch Verwendung für Eure Art.", sourceObjectiveStatus = "unverified-source-field" }
quests[47219] = { id = 47219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein taugliches Medium", description = "Nach reiflicher Überlegung habe ich entschieden, Alleria eine weitere Gelegenheit zu gewähren, ihr Schicksal zu erfüllen.\n\nIhr wollt sicherlich wissen, was dies bedeutet, <Sterblicher/Sterbliche>.\n\n<Der Raumgänger lacht.>\n\nTrefft uns tief inmitten des Schattenwachenlagers da vorn. Meine Leute werden eine Beschwörung vorbereiten, um genug Energie bereitzustellen, damit Windläufer von vorn beginnen kann.\n\nBezeugt, was geschieht, wenn man die Kräfte der Leere beherrscht.", sourceObjective = "Besiegt Nhal'athoth und entnehmt ihm sein Herz.", progress = "Ich kann den Weg deutlich sehen, {name}.", completion = "<Alleria nimmt das Herz in die Hände.>\n\nDas ist der nächste Schritt, {name}. Danke, dass Ihr mich so weit gebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[47220] = { id = 47220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Signal im Dunklen", description = "Das war... ein aufreibendes Erlebnis.\n\n<Alleria reibt sich die Stirn.>\n\nIch kann mich kaum konzentrieren. Ihr müsst zu Velen zurückgehen und ihm das hier geben.\n\n<Sie legt Euch etwas Kaltes und Kompaktes in die Hand.>\n\nIch habe das Gefühl, dass er das hier bekommen sollte, aber ich weiß nicht warum.\n\nErzählt ihm, was wir erfahren haben. Romuul wird unsere Fortschritte sicher beobachtet haben. Mit etwas Glück ist bereits ein Signal auf dem Weg zu uns.", sourceObjective = "Bringt die Überreste von Nhal'athoth zu Velen auf der Vindikaar.", progress = "Was ist das? Solche Dunkelheit...", completion = "Was bringt Ihr da, {name}?\n\n\n\nFaszinierend...", sourceObjectiveStatus = "unverified-source-field" }
quests[47221] = { id = 47221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hand des Schicksals", sourceObjective = "Trefft Euch mit Eurer Eskorte zur Exodar im Hafen von Sturmwind.", completion = "Ich bin froh, dass auch Ihr für die Expedition nach Argus ausgewählt wurdet. Es warten jede Menge Kämpfe auf uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[47222] = { id = 47222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwei übers Meer", description = "Das Grabmal des Sargeras war erst der Anfang. Wenn wir die Legion nicht vollständig vernichten, wird sie noch stärker zurückkehren.\n\nWir werden auf dem Seeweg zur Azurmythosinsel reisen, um nicht unnötig Aufmerksamkeit zu erregen. Je weniger Zeit die Legion hat, um auf unseren Angriff zu reagieren, desto besser.\n\nSagt einfach Bescheid, wenn Ihr bereit zur Abreise seid.", sourceObjective = "Sprecht mit Vereesa Windläufer, um zur Exodar aufzubrechen.", completion = "Möge das Licht uns alle an diesem Tage beschützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[47223] = { id = 47223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exodus des Lichts", description = "Prophet Velen und die anderen haben sich da unten in der Halle des Lichts versammelt. Der Eingang ist am Ende dieses Pfades.\n\nWir sollten sofort den Propheten aufsuchen, damit wir die Invasion nicht aufhalten.", sourceObjective = "Trefft Prophet Velen in der Halle des Lichts in der Exodar.", completion = "Dem Licht sei Dank, dass Ihr es geschafft habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[47224] = { id = 47224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vindikaar", description = "Es ist alles für den Angriff vorbereitet. Wir müssen nur noch das Signal für den Transport zum Schiff einrichten.\n\nLegt Eure Hand auf die Oberfläche des Signals, wenn es eintrifft, damit es Euch zur Vindikaar, dem Instrument unserer Vergeltung, bringen kann.", sourceObjective = "Geht an Bord der Vindikaar.", progress = "Heute ist der erste Tag des Endes der Legion.", completion = "Ich habe so viele Jahre auf diesen Tag gewartet.\n\nBewundert den Triumph der Draenei: die Vindikaar!", sourceObjectiveStatus = "unverified-source-field" }
quests[47226] = { id = 47226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Waisenjunge", description = "<Das überlebende Junge quäkt mitleiderregend, während es den Leichnam seiner Mutter anstarrt.\n\nEs mustert Euch hoffnungsvoll und scheint Euch folgen zu wollen.\n\nVielleicht könnt Ihr jemanden im Kriegsbestienkral finden, der sich darum kümmert?>", sourceObjective = "Findet jemanden im Kriegsbestienkral, der sich um das Terrorhornjunge kümmert.", completion = "Seid Ihr der Hordefremdling, von dem ich schon so viel gehört hab? Ich dacht, Ihr wärt 'n bisschen größer. Ha!\n\nHey! Was habt Ihr'n da?", sourceObjectiveStatus = "unverified-source-field" }
quests[47228] = { id = 47228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tierpopulation von Xibala", description = "Ich hatte wirklich gehofft, dass dieses Gebiet etwas weniger unwirtlich sein würde.\n\nDie Zandalari haben keinerlei Hilfe geleistet, um diese Gegend für archäologische Erkundungen vorzubereiten. Bevor wir uns um Xibalas Geheimnisse kümmern können, müssen wir das Gebiet auch für jene sichern, die nicht kämpfen können.\n\nIn den Ruinen da vorn treiben sich alle möglichen Raubtiere herum. Die wenigen unerschrockenen Forscher, die sich dort hineingewagt haben, sind nicht zurückgekehrt.\n\nDie Tierpopulation darf dem Fortschritt nicht im Wege stehen, {name}. Habt Ihr das verstanden?", sourceObjective = "Tötet 8 Raubtiere von Xibala.", completion = "Ich höre, in dieser Gegend sprießt solches Leben förmlich. Ihr Bestand wird sich erholen... an einem anderen Ort.", sourceObjectiveStatus = "unverified-source-field" }
quests[47229] = { id = 47229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bollwerk von Torcali", description = "Wir ham die alte Rotana nochmal auf die Beine gebracht. Schnappt Euch die Zügel un' steigt auf.\n\nGebt uns Deckung, damit Talanji sich von ihrer Seite aus 'n Weg reinbahn'n kann.", sourceObjective = "Reitet auf der alten Rotana in den Kampf gegen die Bluttrolle.", completion = "Ich danke Euch! Wir können aber nicht hierbleib'n. Es werd'n mehr Bluttrolle kommen. Wo is' mein Vater?", sourceObjectiveStatus = "unverified-source-field" }
quests[47235] = { id = 47235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Hellsicht zum Auge", description = "Wir suchen im Auftrag der Horde nach einem Relikt namens \"Auge von Xibala\".\n\nDie Einheimischen waren bis jetzt überhaupt keine Hilfe und Fräulein Tae'shara besteht darauf, dass wir ihre Erkundungsausrüstung benutzen.\n\nAber ich hasse Spekulation, also werden wir stattdessen eine direktere Methode anwenden: Hellsehen.\n\nIch werde drei Stellen auf Eurer Karte markieren und möchte, dass Ihr an jeder Position ein Sehergerät aufstellt. Mithilfe ihrer Messungen werde ich den Ort des Relikts bestimmen, und wir können uns endlich auf den Weg machen.", sourceObjective = "Stellt 3 Sehergeräte in Xibala auf.", completion = "Ausgezeichnete Arbeit. Lasst mich nun die Ergebnisse überprüfen, damit wir uns auf den Weg machen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[47238] = { id = 47238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sitz des Triumvirats", description = "Selbst mit dem Siegel des Erwachens kann uns die Krone nicht schützen, solange sie nicht vollständig ist.\n\nDarum müssen wir in den Sitz des Triumvirats eindringen, auch wenn L'ura uns dort schon erwartet.\n\nDas ist eine brutale Aufgabe und ich würde Euch nicht darum bitten, wenn es nicht absolut notwendig wäre.\n\nWir gehen zusammen runter. Kommt.", sourceObjective = "Sucht nach dem Wappen des Wissens.", completion = "Das sind in der Tat beunruhigende Neuigkeiten. Es wäre weise, von nun an Alleria zu folgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[47241] = { id = 47241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schatten des Todes", description = "Wir ham vier Loa, aber wiss'n nur, wo einer is': Bwonsamdi.\n\nSo unwohl mir dabei auch is', ich bin zu allem bereit, um die Bluttrolle aufzuhalt'n, selbst wenn es bedeutet, dass wir uns mit'm Loa des Todes einlass'n müss'n.\n\nVor langer Zeit hatte Bwonsamdi hier in Nazmir 'nen Tempel. Meine Hellsicht hat offenbart, dass es im Norden ein paar Orte mit 'ner magischen Präsenz gibt. Sucht dort nach Hinweisen.\n\nBeeilt Euch, {name}. Ohne Bwonsamdis Hilfe wird Zuldazar fall'n!", sourceObjective = "Sucht nach Hinweisen zum Aufenthaltsort des Loas Bwonsamdi.", completion = "Ihr sucht Bwonsamdis Tempel? Ihr müsst ganz schön verzweifelt sein, wenn Ihr da hinwollt.\n\nAber heute is' Euer Glückstag, ich geh da nämlich gerade selber hin.", sourceObjectiveStatus = "unverified-source-field" }
quests[47244] = { id = 47244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Seelenausmerzung", description = "Heutzutage betret'n bloß noch jene Bwonsamdis Tempel, die entweder tot sin' oder 'n Geschäft mach'n woll'n. Ihr riecht nich' sonderlich vermodert, also gehört Ihr wohl zur zweit'n Kategorie.\n\nIch geh grade selber zum Tempel, also wie wär's mit 'nem Geschäft?\n\nEs gibt hinter der Brücke drüb'n 'ne Hexe namens Najima, un' der bin ich schon 'n Weilchen auf der Spur. Die Bluttrolle sind zwar verderbt bis aufs Mark, aber ihre Seel'n sin' gute Opfergaben für Bwonsamdi. Ich allein werd mit ihr nich' fertig, aber wenn Ihr sie umlegt, bring ich Euch in'n Tempel.\n\nIch geb Euch mein Wort.", sourceObjective = "Besiegt Bluthexe Najima.", completion = "Das sollte reich'n, Mann. Ihre Seele is' die perfekte Opfergabe.\n\nAber bevor wir zum Tempel geh'n, wär da noch 'ne Sache zu erledig'n...", sourceObjectiveStatus = "unverified-source-field" }
quests[47245] = { id = 47245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachricht kommt an", description = "Der Loa is' mächtig, aber wir werd'n Soldaten brauch'n, wenn wir verhindern woll'n, dass die Bluttrolle ihr Riesending bau'n. Wenn wir das Ding nich' zerstör'n, bevor es fertig is', dann sind Zuldazar un' unser Volk so gut wie platt!\n\nWir brauch'n die Hilfe der Horde!\n\nEin Bote is' schon aufm Weg zum Kriegshäuptling. Sobald wir Rückmeldung ham, können wir...\n\nMoment mal! Was is' das für 'n Lärm?", sourceObjective = "Untersucht die Störung.", completion = "Goblins... Warum musste der Kriegshäuptling uns von allen würdig'n Einheiten in der Horde ausgerechnet Goblins schick'n?", sourceObjectiveStatus = "unverified-source-field" }
quests[47246] = { id = 47246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überreste der Verdammten", description = "Seit die Geister dies'n \"G'huun\" anruf'n, is' mein Tempel mit der unerträglich'n Verderbnis der Untot'n überzog'n.\n\nDie Untot'n sind zwar Monstrosität'n, aber die Blutsteine, die sie erzeug'n, die sind richtig mächtig und könnt'n für Bwonsamdi noch nützlich werd'n.\n\nWenn Ihr mir zeig'n wollt, wie es so um Eure Inbrunst bestellt is', dann säubert meinen Tempel von diesem Dreck un' bringt mir ihre Blutsteine.", sourceObjective = "Sammelt 6 verwesende Blutsteine für Bwonsamdi.", sourceObjectiveStatus = "unverified-source-field" }
quests[47247] = { id = 47247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Heimsuchung der Toten", description = "Bwonsamdi weiß, warum Ihr hier seid. Ihr braucht 'nen Gefallen.\n\n<Bwonsamdi mustert Euch schweigend.>\n\nEin Test, um zu seh'n, ob Ihr Bwonsamdis Zeit würdig seid.\n\nEs gibt Geister, die in ihren Gebet'n einen gewiss'n \"G'huun\" besing'n und mich nich' mehr verehr'n. Un' ich werd' ja wohl nich' zulass'n, dass jemand meinen Tempel entweiht!\n\nAlso geht un' besiegt den stärksten uralt'n Geist für mich.\n\nWenn Ihr das macht, dann seid Ihr meine Zeit un' Mühe vielleicht wert.", sourceObjective = "Besiegt Hexpriesterin Tizeja und Kriegsfürstin Malaja.", completion = "Ach, ich spür schon, wie ihre Seelen meine Kräfte stärk'n. Ich hab doch gewusst, dass Bwonsamdi seine Zeit gut in Euch investiert hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[47248] = { id = 47248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bis dass der Tod uns scheidet", description = "Ich weiß zwar nich', wer Ihr seid, aber ich brauch Eure Hilfe.\n\nMein geliebter Valjabu hat immer gesagt, dass ihm das Priestergelübde egal is' un' dass wir für immer zusamm' sein würd'n.\n\nTja, meine Zeit is' nun gekomm', un' ich hab gewusst, dass ich nich' ohne ihn weiterzieh'n kann. Also bin ich hierher zurückgekomm' un' hier für 'ne Ewigkeit herumgegeistert... Aber Valjabu is' nie aufgetaucht!\n\nIch irr jetz' schon viel zu lange auf dieser Welt 'rum.\n\nBitte, ich fleh Euch an. Bringt mir 'n Andenken an Valjabu!", sourceObjective = "Beschafft Valjabus Hauerring.", progress = "Habt Ihr Valjabu schon gefund'n? Seine Urne is' hier irgendwo.", completion = "<Salazae wirkt verzweifelt.>\n\nAch, Valjabu... warum bist du nur ohne mich gegang'n?\n\n<Eine geisterhafte Träne rinnt über ihre Wange.>\n\nDanke, Fremder. Jetzt kann ich endlich in Frieden geh'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[47249] = { id = 47249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seelengebunden", description = "Ihr habt Euch bei meinen Aufgab'n gut geschlag'n. Das war ziemlich vielversprechend un' ich glaub, ich könnt mich mit Euch auf 'nen Pakt einlass'n.\n\nAlso gut, ich werd Euch meine Kräfte für den Kampf geg'n Eure Feinde gewähr'n. Im Austausch müsst Ihr Bwonsamdi eine Million Seelen liefern! Da braucht Ihr nich' gleich zu erschreck'n... Jemand wie Ihr schafft das locker.\n\nKommt, geh'n wir zum Hof der Seelen. Dort werd'n wir unseren Pakt besieg'ln.", sourceObjective = "Sprecht mit Bwonsamdi im Hof der Seelen und schließt das Ritual ab.", completion = "Die Bluttrolle un' ihr \"Gott\" G'huun sind 'ne deutlich größere Bedrohung, als ich gedacht hab. Das Ritual, um den Pakt mit Euch zu besiegeln is' zwar nich' abgeschloss'n, aber ich denk mal, dass wir unter den Umständen auf die Formalitäten pfeif'n könn'.\n\nSolange am Ende der Preis bezahlt wird, könnt Ihr auf Bwonsamdis Hilfe zähl'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[47250] = { id = 47250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir sehen uns wieder", description = "Es is' jetzt Zeit, dass Ihr geht.\n\nIhr habt für Bwonsamdi noch 'ne Menge Bluttrollseelen auf die Andre Seite zu schick'n un' hier findet Ihr ganz bestimmt keine mehr.", sourceObjective = "Reist zu den Ruinen von Zo'bal und sprecht mit Hanzabu.", completion = "Ihr habt also auch 'nen Pakt mit Bwonsamdi geschloss'n? Gut! Je mehr Seel'n Bwonsamdi bekommt, desto stärker wird er, un' das is' für uns beide das Beste. Lasst bloß Hanzabu noch was zu jag'n übrig. Ich hab schließlich auch 'nen Pakt, den ich einhalt'n muss!", sourceObjectiveStatus = "unverified-source-field" }
quests[47251] = { id = 47251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Interessante Zeiten", description = "{name}, ich will Euch ja nicht grundlos beunruhigen, aber es wird vielleicht ein paar... temporale Störungen geben.\n\nKennt Ihr den Spruch: \"Ich hoffe, die Vergangenheit wird mich nicht einholen\"?\n\nBesucht mich im Tal der Geister, damit wir uns weiter unterhalten können.", sourceObjective = "Trefft Euch mit Historiker Ju'pa im Tal der Geister in Orgrimmar.", completion = "{name}, da seid Ihr ja. Ihr habt also meinen Brief erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[47252] = { id = 47252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Interessante Zeiten", description = "{name}, ich will Euch ja nicht grundlos beunruhigen, aber es könnte ein paar... temporale Störungen geben.\n\nKennt Ihr den Spruch: \"Ich hoffe, die Vergangenheit wird mich nicht einholen\"?\n\nBesucht mich in der Königlichen Bibliothek von Sturmwind, damit wir uns weiter unterhalten können.", sourceObjective = "Trefft Euch mit Historiker Llore in der Königlichen Bibliothek von Sturmwind.", completion = "{name}, da seid Ihr ja. Ihr habt also meinen Brief erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[47253] = { id = 47253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Originale", description = "Vor langer Zeit wanderten große Schrecken durch unsere Lande und trieben selbst die Kleinsten zu Höhenflügen des Heldentums.\n\nIch rede natürlich über Lord Kazzak, Azuregos und den Drachen des Alptraums.\n\nDen Legenden zufolge waren ihre Schätze so begehrt, dass Armeen Nachtlager aufschlugen, um sie zu jagen.\n\nWir vernahmen Störungen in den Zeitlinien, die zufällig an den Plätzen liegen, an denen diese Riesen einst gelebt haben.\n\nKönntet Ihr für uns bitte genauer nachforschen? Zu dieser Jahreszeit geschehen merkwürdige Dinge.", sourceObjective = "Besiegt Lord Kazzak in den Verwüsteten Landen, Azuregos in Azshara und den Drachen des Alptraums bei einem der Portale zum Smaragdgrünen Traum.", completion = "Nutzen wir den Moment, um über die Vergangenheit nachzudenken, damit wir nicht vergessen, was wir aus ihr gelernt haben. Sonst sind wir dazu verdammt, sie zu wiederholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[47254] = { id = 47254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Originale", description = "Vor langer Zeit wanderten große Schrecken durch unsere Lande und trieben selbst die Kleinsten zu Höhenflügen des Heldentums.\n\nIch rede natürlich über Lord Kazzak, Azuregos und die Drachen des Alptraums.\n\nDen Legenden zufolge waren ihre Schätze so begehrt, dass Armeen Nachtlager aufschlugen, um sie zu jagen.\n\nDie Drachen vernahmen Störungen in den Zeitlinien, die zufällig an den Plätzen liegen, an denen diese Riesen einst gelebt haben.\n\nSie haben mich damit beauftragt, Champions zu finden, die der Sache nachgehen.", sourceObjective = "Besiegt Lord Kazzak in den Verwüsteten Landen, Azuregos in Azshara und den Drachen des Alptraums bei einem der Portale zum Smaragdgrünen Traum.", completion = "Nutzen wir den Moment, um über die Vergangenheit nachzudenken, damit wir nicht vergessen, was wir aus ihr gelernt haben. Sonst sind wir dazu verdammt, sie zu wiederholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[47255] = { id = 47255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[47256] = { id = 47256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[47257] = { id = 47257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Knochen von Xibala", description = "Weit im Süden befinden sich die Knochen einer uralten Kreatur. Das ist Xibala, die Urahnin und Erste der Teufelssaurier. Sie war die Mutter von Rezan und aller anderen, die danach kamen. Die Zandalari leben nicht in diesem Gebiet, denn es gehört jetzt den Bestien.\n\nIch habe gehört, dass ein paar Leute Eurer Horde zwischen ihren Knochen nach irgendetwas suchen.\n\nDas ist keine gute Idee. Würdet Ihr Euch vielleicht darum kümmern?", sourceObjective = "Reist zu Xibala und sprecht mit Prüferin Tae'shara Blutwächter.", completion = "Auf so einen Fund habe ich mein Leben lang gewartet. Mein Vater wird sehr stolz auf mich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[47258] = { id = 47258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorbereitung auf eine Belagerung", description = "Wir müss'n uns wohl auf eine Belagerung einstell'n. Kehrt vorerst zu Eurer Horde in Dazar'alor zurück und bereitet Euch auf den kommenden Kampf vor.\n\nWenn die Streitkräfte aus Nazmir hier auftauch'n, werd ich nach Euch schick'n.", sourceObjective = "Sprecht mit Baine Bluthuf.", completion = "Unserem Kriegshäuptling mögen weitere Verzögerungen vielleicht nicht gefallen, aber ich denke, die Ehre gebietet uns, den Zandalari beizustehen.\n\nHier geht es um mehr als nur darum, einen Verbündeten für den Krieg zu gewinnen. Die Horde wurde mit dem Ideal gegründet, jenen zu helfen, die in Not sind.\n\nSo wie Thrall einst meinem Volk zu Hilfe kam, so müssen wir helfen, Zandalar zu beschützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[47259] = { id = 47259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terrorhorn-Betreuung", description = "Tierführer Bazkoji hatte 'ne ganz besondere Beziehung zu den Kleinen. Wenn das Junge jetzt Euch folgt, dann muss das bedeut'n, dass Bazkoji tot is'.\n\nIch hab keine Zeit, 'nen neuen Tierführer zu find'n, der es bei sich aufnimmt. Könnt Ihr das nicht übernehm'n?\n\nEs is' viel Arbeit, aber der kleine Racker lernt schnell. Wenn Ihr Euch um ihn kümmert, is' das 'ne ernsthafte Verpflichtung. Das Baby is' von Euch abhängig. Ich hoff, Ihr schafft das, es zu füttern und es vor allen Gefahren zu beschütz'n.\n\nAber das Wichtigste zuerst: Essen. In den Pferch'n und unten am Fluss gibt's reichlich Futter.", sourceObjective = "Füttert Euer Junges.", completion = "Gar nich' übel. Der Kleine sieht schon viel kräftiger aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[47260] = { id = 47260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mögliche Nebenwirkungen...", description = "<Euer Terrorhornbegleiter hickst wiederholt und schrumpft oder wächst jedes Mal merklich, dazu winselt er voller Verzweiflung.\n\nIhr könntet etwas Hilfe gebrauchen.>", sourceObjective = "Sprecht mit Abrichterin L'kala im Kriegsbestienkral.", completion = "Ich hab gewusst, dass es keine gute Idee war, diesem kleinen, grünen Mann zu vertrau'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[47261] = { id = 47261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terrorhornzähmen leicht gemacht", description = "Oh, Mann! Ich glaub', ich will auch was von dem Zeug, das Ihr dem Kleinen gebt!\n\nEr is' jetzt schon so groß, dass er lern' muss, 'n verlässlicher Kampfgefährte zu sein.\n\nMal seh'n, wie er mit 'ner härteren Herausforderung umgeht, hm?\n\nSprecht mit Kralmeister B'khor, wenn's losgeh'n kann.", sourceObjective = "Sprecht mit Kralmeister B'khor und wählt die Ausbildung für Euer Terrorhorn.", completion = "Oho! Immerhin hat's Spaß gemacht, das zu seh'n! Hahaha!\n\nIch glaub', Ihr habt Euch Euren Platz hier so was von verdient!", sourceObjectiveStatus = "unverified-source-field" }
quests[47262] = { id = 47262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende der Bluttrolle", description = "Die Loa meinen's heute gut mit uns. Die \"Matriarchin\" dieser Bluttrolle, so 'n krankes Monster namens Ateena, is' gleich da vorne.\n\nDas verlangt nach 'ner Planänderung, {name}. Wir werd'n die Sache hier un' jetzt beend'n. Wir bringen Ateena um, das wird die Bluttrolle ins Chaos stürz'n.\n\nSie's 'ne mächtige Verhexerin, also werdet Ihr sie angreif'n, damit ich sie dann aus dem Hinterhalt überrasch'n kann.\n\nAlso dann mal los. Wir müss'n vor Tagesende wieder in Zuldazar sein.", sourceObjective = "Tötet Ateena, die Matriarchin der Bluttrolle.", completion = "Ateena wird uns nich' entkommen, wir müss'n weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[47263] = { id = 47263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Zeit der Offenbarung", description = "Ich spür Ateenas dunklen Voodoo vor uns. Wir müss'n ihre Pläne für dies'n \"G'huun\" durchkreuz'n.\n\nSeid auf alles gefasst, {name}. Wir kenn' Ateenas wahre Macht nich'.\n\nEins weiß ich aber. Wenn G'huun mein Volk bedroht, dann wird er sterb'n, genau wie Ateena.", sourceObjective = "Helft Talanji, Ateena aufzuspüren.", completion = "Die Bedrohung durch die Bluttrolle is' größer, als ich je gedacht hab. Das Konstrukt reicht, um ganz Zuldazar zu zerstör'n.\n\nWir brauch'n mehr als die Horde, um dem ein Ende zu setz'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[47264] = { id = 47264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst keinen am Leben!", description = "Jetzt seht Ihr ja, was mein Vater nich' zugeb'n will. Die Bluttrolle schlag'n uns... Und sie müss'n aufgehalt'n werd'n.\n\nUnser Plan is' simpel, {name}. Wir geh'n da raus un' bring'n so viele Bluttrolle wie möglich um. Ihr geht nach Ost'n, ich nach Nord'n.\n\nDanach treff'n wir uns wieder un' guck'n, was noch zu tun is'. Wir werd'n dies'n Bluttrollen noch beibring'n, die Zandalari zu fürcht'n!", sourceObjective = "Tötet 6 Bluttrolle.", completion = "Seid Ihr fertig? Wir sin' kurz davor, dieser Bedrohung den Garaus zu mach'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[47272] = { id = 47272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wachstumshormon für Terrorhörner", description = "Ein nettes Tierchen habt Ihr da. In dieser mickrigen Größe ist es allerdings nicht sonderlich bedrohlich.\n\nWollt Ihr bei einem kleinen Geschäft mithelfen? Hier gibt es so viele Möglichkeiten, aber diese Trolle wollen mir einfach nicht zuhören!\n\nAlso, ich kann Euch etwas zusammenstellen, das Euch Haare auf der Brust wachsen lässt... Äh, Haare auf der Brust des Terrorhorns, meine ich.\n\nIch weiß, dass Terrorhörner eigentlich Vegetarier sind, aber es gibt ja einen guten Grund dafür, warum die größten Raubtiere Fleisch fressen!\n\nSchnelles Wachstum erfordert Protein. SEHR VIEL Protein.\n\nSeid Ihr interessiert?", sourceObjective = "Sammelt 10 dampfendes frisches Aas.", progress = "Und? Habt Ihr alles, was ich benötige?", completion = "Fleisch ist wirklich erstaunliches Zeug!\n\nAber... Ich glaube, es ist besser, wenn Ihr die Details über diese Sache vorerst für Euch behaltet.", sourceObjectiveStatus = "unverified-source-field" }
quests[47283] = { id = 47283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg damit!", description = "Throm-ka, {name}.\n\nIch suche immer Leute, die die Axt wie ein Profi schwingen können.\n\nWenn Ihr den Setzling ohne viel Aufhebens entfernen könnt, werden wir bestimmt eine bessere Verwendung für Eure Fähigkeiten finden.", sourceObjective = "Nehmt Euch eine robuste Axt und sammelt 5 Scheite frisch gespaltenes Holz von dem Setzling in der Nähe.", completion = "Genau die Art von Stärke, die wir hier gebrauchen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[47287] = { id = 47287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Matrixkern der Vindikaar", description = "Auf Argus ist vieles geschehen, das mir Sorgen bereitet. Am meisten aber Xe'ras Schicksal. Ich frage mich manchmal, ob wir das Richtige tun.\n\nAber wir müssen weitermachen. Ich kann den Matrixkern der Vindikaar instand setzen, sodass Ihr die Kraft unserer Kanonen nutzen könnt, wenn Ihr sie auf dem Planeten braucht. \n\nBegebt Euch zum Matrixkern im Zentralraum unseres Schiffs. Wenn die Verbindung erst einmal hergestellt ist, verfügt Ihr über alle Kräfte, die der Kern jetzt und in aller Zukunft in sich birgt.", sourceObjective = "Verbindet das Urteil des Lichts mit dem Matrixkern der Vindikaar.", completion = "Wenn Ihr jetzt die Matrixsignalverbindung verwendet, feuert das Urteil des Lichts auf Euren Befehl hin.\n\nVielleicht findet Ihr auf Euren Reisen noch weitere Objekte, die wir mit der Matrix verbinden können. Ich habe diesen Teil des Kerns mit ausreichend Energie versehen, sodass Ihr alles nutzen könnt, das sich damit verbinden lässt. \n\nMacht es gut, mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[47288] = { id = 47288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wertvolle Fossilien" }
quests[47289] = { id = 47289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tierische Teestunde", description = "Hier gibt's niemanden mehr, der mit mir spielt. Aber Ihr spielt doch mit mir, oder?\n\nEs ist Zeit für die Teestunde! Helft mir doch bitte, die anderen Gäste zu finden!", sourceObjective = "Bringt Herrn Leckermaul, Rüsselchen und Bürgermeister Stricks zu einem Teekränzchen zusammen.", progress = "Das wird das beste Teekränzchen aller Zeiten!", completion = "Hurra! Nur noch ein Gast zu finden!", sourceObjectiveStatus = "unverified-source-field" }
quests[47290] = { id = 47290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "World Event Dungeon - Hummel" }
quests[47310] = { id = 47310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nickerchen", description = "Euer gar nich' mal so kleines Junges sieht nach diesem aufregend'n Tag etwas zerrupft aus. Ich wette, Ihr braucht beide 'ne Pause, hm?\n\nKommt später wieder, wenn Ihr Euch 'n bisschen erholt habt.", sourceObjective = "Bringt Euer Terrorhorn im Tierpferch unter.", completion = "Ich werd' 'ne Weile auf Euren Kleinen aufpass'n. Macht Euch auf zu Euern Abenteuern! Lernt die Lebensart der Zandalari kenn'. Wenn Ihr beide bereit seid, hab' ich 'n Angebot für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[47311] = { id = 47311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfstoß für Anfänger", description = "Euer Tier sieht echt gut genährt aus. Gut. Macht genau so weiter.\n\nAls Nächstes müsst Ihr Eurem kleinen Schützling beibring'n, wie er sich verteidigt. In der freien Wildbahn sin' Terrorhörner aufm Speiseplan von viel größ'ren Kreaturen un' besonders die Jungen sind leichte Beute für Sauriden und andre Jäger.\n\nGeht in die Wilden Lande un' bringt Eurem Kleinen bei, wie man Feinde abwehrt.\n\nDas Horn is' der Schlüssel, {name}.", sourceObjective = "Unterstützt Euer Jungtier im Kampf gegen 12 Kreaturen.", completion = "Ich seh' 'nen kleinen Anflug von Selbstvertrau'n in den Augen von Eurem Schützling. Gut. Das wird er brauch'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[47312] = { id = 47312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Federkönigin", description = "Ah, Ihr seid also <der, der/die> die; Bazkojis Herde übernomm' hat. Zumindest das, was davon übrig is'.\n\nIch weiß, was ihn getötet hat un' ich hab ihn gewarnt. Federkönigin is' 'ne mächtige Ravasaurusdame un' die is' größer un' schlauer als alle andren. Die meist'n Eier hier sin' von ihr.\n\nNormalerweise würd ich die Stärke von so 'nem Tier bewundern, aber sie is' zu 'ner richtigen Bedrohung geword'n.\n\nIhr findet sie in den Futtergründen, wo sie ihre Nester bewacht. Tötet sie un' bringt mir 'ne Kopffeder von ihr als Beweis für ihr'n Tod.", sourceObjective = "Tötet Federkönigin und nehmt eine ihrer Federn an Euch.", progress = "Is' uns Federkönigin immer noch auf den Fers'n?", completion = "Gut. Jetzt, wo die blutrünstige Matriarchin Geschichte is', könn'n wir vielleicht eins unsrer Tiere für die Brut einsetzt'n. Praktisch als Ersatz... hmmm.", sourceObjectiveStatus = "unverified-source-field" }
quests[47313] = { id = 47313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diskrete Gespräche", description = "General Jakra'zet is' nich' zu trau'n.\n\nEr hat irgendwas vor, aber ich weiß nich', was es is'.\n\nWer seine Befehle hinterfragt, den schickt er gradewegs in die Sande.\n\nSolang er an der Macht is', is' meine Stadt nich' sicher.\n\nSprecht mit seinen Wach'n und seht, was Ihr herausbekommen könnt, aber seid so diskret wie möglich. Wir woll'n ja schließlich nich', dass Jakra'zet Verdacht schöpft.", sourceObjective = "Befragt Vollstrecker innerhalb von Dazar'alor.", progress = "Es ist zu gefährlich, hier Fragen nach dem General zu stell'n.", completion = "Wenn Ihr hier solche Frag'n stellt, werdet Ihr Euch mehr Feinde als Freunde mach'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[47314] = { id = 47314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exilgerüchte", description = "Talanji hat Euch geschickt, was? \n\nDie Prinzessin sollte wiss'n, dass es nich' mehr sicher is', off'n solche Frag'n zu stell'n... \n\nKriegswache Rakera war so unvorsichtig un' seitdem hat keiner mehr was von ihr gehört.\n\nAngeblich wurd' sie nach Vol'dun verbannt.", sourceObjective = "Folgt Klingenwache Kaja.", completion = "Wir werd'n nich' zulass'n, dass Rakera mit ihrem Wiss'n in den Sanden verschwindet.", sourceObjectiveStatus = "unverified-source-field" }
